(() => {
  'use strict';

  const SETTINGS_KEY = 'settings';
  const FEEDBACK_KEY = 'feedback';
  const DEFAULT_SETTINGS = { autoHide: true };

  const RULE_LABELS = {
    'ai-generated': 'Explicit AI-generated wording',
    'generated-by-ai': 'Generated by AI wording',
    'made-with-ai': 'Made/created using AI wording',
    'ai-tool-disclosure': 'Named AI image tool disclosure'
  };

  const checkbox = document.getElementById('auto-hide');
  const status = document.getElementById('status');

  function load() {
    chrome.storage.local.get({ [SETTINGS_KEY]: DEFAULT_SETTINGS, [FEEDBACK_KEY]: {} }, (data) => {
      const settings = { ...DEFAULT_SETTINGS, ...(data[SETTINGS_KEY] || {}) };
      checkbox.checked = Boolean(settings.autoHide);
      renderFeedback(data[FEEDBACK_KEY] || {});
    });
  }

  function renderFeedback(feedback) {
    const totals = feedback.totals || {};
    document.getElementById('false-positive-count').textContent = totals.falsePositive || 0;
    document.getElementById('confirmed-count').textContent = totals.confirmed || 0;

    const container = document.getElementById('rule-stats');
    container.replaceChildren();

    for (const [ruleId, counts] of Object.entries(feedback.byRule || {})) {
      const item = document.createElement('p');
      const label = RULE_LABELS[ruleId] || ruleId;
      item.textContent = `${label}: ${counts.falsePositive || 0} false positive(s), ${counts.confirmed || 0} confirmed`;
      container.appendChild(item);
    }

    if (!container.childElementCount) {
      container.textContent = 'No rule-level feedback yet.';
    }
  }

  checkbox.addEventListener('change', () => {
    chrome.storage.local.set({ [SETTINGS_KEY]: { autoHide: checkbox.checked } }, () => {
      status.textContent = checkbox.checked
        ? 'Automatic hiding enabled.'
        : 'Posts will be flagged but not hidden.';
    });
  });

  document.getElementById('export-feedback').addEventListener('click', () => {
    chrome.storage.local.get({ [FEEDBACK_KEY]: {} }, ({ feedback }) => {
      const blob = new Blob([
        JSON.stringify({ exportedAt: new Date().toISOString(), feedback }, null, 2)
      ], { type: 'application/json' });

      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = 'ai-eraser-feedback.json';
      link.click();
      URL.revokeObjectURL(url);

      status.textContent = 'Feedback exported.';
    });
  });

  document.getElementById('clear-feedback').addEventListener('click', () => {
    chrome.storage.local.set({
      [FEEDBACK_KEY]: { totals: { falsePositive: 0, confirmed: 0 }, byRule: {} }
    }, load);

    status.textContent = 'Feedback cleared.';
  });

  load();
})();
